pub fn deinit(self: *S3Client) void {
            _ = self.credentials.deref();
            _ = destroy(self);
    }

pub fn finalize(self: *S3Client) void {
            _ = self.deinit();
    }

pub fn staticWrite(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            return S3File.write(globalThis, callframe);
    }

pub fn staticPresign(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            return S3File.presign(globalThis, callframe);
    }

pub fn staticExists(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            return S3File.exists(globalThis, callframe);
    }

pub fn staticSize(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            return S3File.size(globalThis, callframe);
    }

pub fn staticUnlink(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            return S3File.unlink(globalThis, callframe);
    }

pub fn staticFile(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            const arguments = callframe.arguments_old(2).slice();
            var args = jsc.CallFrame.ArgumentsSlice.init(globalThis.bunVM(), arguments);
            _ = &args;
            defer {
            _ = args.deinit();
            }
            const path = ((try jsc.Node.PathLike.fromJS(globalThis, (&args))) orelse {
            return globalThis.throwInvalidArguments("Expected file path string", .{});
});
            return try S3File.constructInternalJS(globalThis, path, args.nextEat());
    }

pub fn staticStat(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            return S3File.stat(globalThis, callframe);
    }

pub fn staticListObjects(globalThis: *JSGlobalObject, callframe: *jsc.CallFrame) JSError!JSValue {
            const args = callframe.argumentsAsArray(2);
            const object_keys = args[0];
            const options = args[1];
            const existing_credentials = globalThis.bunVM().transpiler.env.getS3Credentials();
            var blob = try S3File.constructS3FileWithS3Credentials(globalThis, .{ .string = PathString.empty }, options, existing_credentials);
            _ = &blob;
            defer {
            _ = blob.detach();
            }
            return blob.store.?.data.s3.listObjects(blob.store.?, globalThis, object_keys, options);
    }
    const log = Output.scoped(.S3Client, .visible);
    pub const js = jsc.Codegen.JSS3Client;
    pub const toJS = js.toJS;
    pub const fromJS = js.fromJS;
    pub const fromJSDirect = js.fromJSDirect;
    pub const new = TrivialNew(S3Client);
};

const S3Credentials = S3.S3Credentials;
const JSGlobalObject = jsc.JSGlobalObject;
const JSValue = jsc.JSValue;
const Blob = jsc.WebCore.Blob;
const PathOrBlob = jsc.Node.PathOrBlob;

pub fn writeFormatCredentials(credentials: *S3Credentials, options: S3.MultiPartUploadOptions, acl: ?S3.ACL, comptime Formatter: type, formatter: *Formatter, writer: anytype, comptime enable_ansi_colors: bool) !void {
        _ = try writer.writeAll("\n");
        {
            const Writer = @TypeOf(writer);
            formatter.indent = (formatter.indent + 1);
            defer {
            formatter.indent = (if ((formatter.indent > 0)) (formatter.indent - 1) else 0);
            }
            const endpoint = (if ((credentials.endpoint.len > 0)) credentials.endpoint else (if (credentials.virtual_hosted_style) "https://<bucket>.s3.<region>.amazonaws.com" else "https://s3.<region>.amazonaws.com"));
            _ = try formatter.writeIndent(Writer, writer);
            _ = try writer.writeAll(Output.prettyFmt("<r>endpoint<d>:<r> \"", enable_ansi_colors));
            _ = try writer.print(Output.prettyFmt("<r><b>{s}<r>\"", enable_ansi_colors), .{ endpoint });
            _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
            _ = try writer.writeAll("\n");
            const region = (if ((credentials.region.len > 0)) credentials.region else S3Credentials.guessRegion(credentials.endpoint));
            _ = try formatter.writeIndent(Writer, writer);
            _ = try writer.writeAll(Output.prettyFmt("<r>region<d>:<r> \"", enable_ansi_colors));
            _ = try writer.print(Output.prettyFmt("<r><b>{s}<r>\"", enable_ansi_colors), .{ region });
            _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
            _ = try writer.writeAll("\n");
            if ((credentials.accessKeyId.len > 0)) {
                _ = try formatter.writeIndent(Writer, writer);
                _ = try writer.writeAll(Output.prettyFmt("<r>accessKeyId<d>:<r> \"<r><b>[REDACTED]<r>\"", enable_ansi_colors));
                _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
                _ = try writer.writeAll("\n");
            }
            if ((credentials.secretAccessKey.len > 0)) {
                _ = try formatter.writeIndent(Writer, writer);
                _ = try writer.writeAll(Output.prettyFmt("<r>secretAccessKey<d>:<r> \"<r><b>[REDACTED]<r>\"", enable_ansi_colors));
                _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
                _ = try writer.writeAll("\n");
            }
            if ((credentials.sessionToken.len > 0)) {
                _ = try formatter.writeIndent(Writer, writer);
                _ = try writer.writeAll(Output.prettyFmt("<r>sessionToken<d>:<r> \"<r><b>[REDACTED]<r>\"", enable_ansi_colors));
                _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
                _ = try writer.writeAll("\n");
            }
            if (acl) |acl_value| {
                _ = &acl_value;
                _ = try formatter.writeIndent(Writer, writer);
                _ = try writer.writeAll(Output.prettyFmt("<r>acl<d>:<r> ", enable_ansi_colors));
                _ = try writer.print(Output.prettyFmt("<r><b>{s}<r>\"", enable_ansi_colors), .{ cp_string_from(acl_value) });
                _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
                _ = try writer.writeAll("\n");
            }
            _ = try formatter.writeIndent(Writer, writer);
            _ = try writer.writeAll(Output.prettyFmt("<r>partSize<d>:<r> ", enable_ansi_colors));
            _ = try formatter.printAs(.Double, Writer, writer, JSValue.jsNumber(options.partSize), .NumberObject, enable_ansi_colors);
            _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
            _ = try writer.writeAll("\n");
            _ = try formatter.writeIndent(Writer, writer);
            _ = try writer.writeAll(Output.prettyFmt("<r>queueSize<d>:<r> ", enable_ansi_colors));
            _ = try formatter.printAs(.Double, Writer, writer, JSValue.jsNumber(options.queueSize), .NumberObject, enable_ansi_colors);
            _ = try formatter.printComma(Writer, writer, enable_ansi_colors);
            _ = try writer.writeAll("\n");
            _ = try formatter.writeIndent(Writer, writer);
            _ = try writer.writeAll(Output.prettyFmt("<r>retry<d>:<r> ", enable_ansi_colors));
            _ = try formatter.printAs(.Double, Writer, writer, JSValue.jsNumber(options.retry), .NumberObject, enable_ansi_colors);
            _ = try writer.writeAll("\n");
        }
}
